public class Main {
    public static void main(String[] args) throws Exception {
        ProcessBuilder pb = new ProcessBuilder("java", "-version");
        pb.inheritIO();
        Process hijo = pb.start();
        System.out.println("PID hijo: " + hijo.pid());
    }
}

